"""Versioned standalone manuscripts; every numeric cell links to immutable evidence."""
import argparse,csv,json
from pathlib import Path
from .runtime import ROOT,Run,sha,state

def main():
    p=argparse.ArgumentParser();p.add_argument('--revision',choices=['01','02','03','04'],required=True);a=p.parse_args();rev='v3_r'+a.revision;st=state();g2=ROOT/'outputs_v3'/st['g2_run'];g3=ROOT/'outputs_v3'/st['g3_run'];base=json.loads((g2/'raw_metrics.json').read_text())['results'];grid=json.loads((g3/'raw_metrics.json').read_text());selection=grid['selection'];allrows=base+grid['results'];folder=ROOT/'paper/revisions'/rev;folder.mkdir(parents=True,exist_ok=False);bindings=[]
    def get(name,ds='St_Lucia',radius=10):
        m=next(r for r in allrows if r['method']==name and r['dataset']==ds and r['split']=='validation' and r['radius']==radius);src=g2 if m in base else g3
        bindings.append(dict(dataset=ds,split='validation',method=name,radius=radius,unit=m['unit'],run_id=src.name,file=str((src/'raw_metrics.json').relative_to(ROOT)),sha256=sha(src/'raw_metrics.json'),metric_record=m));return m
    timing={};g5=None
    if int(a.revision)>=3:
        assert st.get('g5_run');g5=ROOT/'outputs_v3'/st['g5_run'];actual=json.loads((g5/'raw_metrics.json').read_text());timing={r['method']:r for r in actual['timing']}
    specs=[('A','CosPlace A'),('B','EigenPlaces B'),('DINOv2','DINOv2'),('RRF_k60','RRF'),('AB_0.75','A+B, B weight .75'),('fixed_L9','Fixed L9, v1.2'),('full_L3','Full-velocity L3'),('full_L5','Full-velocity L5'),('full_L9','Full-velocity L9'),('global_fixed_L9_blend_0.75','Global L9 blend .75')]+[(selection['selected'][k]['name'],{'R1':'Local visual R1','R2':'Local fixed blend R2','P':'Support candidate P'}[k]) for k in ['R1','R2','P']]
    main_table=[];table_cells=[]
    for name,label in specs:
        m=get(name);wide=get(name,radius=25);n=get(name,'Nordland',5);line=f"{label} & {m['correct']['1']} & {100*m['recall']['1']:.2f} & {100*wide['recall']['1']:.2f} & {100*n['recall']['1']:.2f}"
        if timing:
            t=timing[name];line+=f" & {t['mean_ms']:.2f} & {t['median_ms']:.2f} & {t['P95_ms']:.2f}";bindings.append(dict(method=name,metric='real_image_timing_mean_median_P95',values=t,run_id=g5.name,file=str((g5/'raw_metrics.json').relative_to(ROOT)),sha256=sha(g5/'raw_metrics.json')))
        main_table.append(line+r'\\');table_cells.append(dict(table='main',method=name,label=label,source_row=line+r'\\',tokens=[str(m['correct']['1']),f"{100*m['recall']['1']:.2f}",f"{100*wide['recall']['1']:.2f}",f"{100*n['recall']['1']:.2f}"]+([f"{timing[name][key]:.2f}" for key in ['mean_ms','median_ms','P95_ms']] if timing else [])))
    chosen=selection['selected']['P'];H=chosen['H'];r=chosen['r'];eps=chosen['epsilon'];ab=[]
